export const meta = {
  name: "bead-worker",
  description: "Process beads from a br workspace. Atomically claims up to maxBeads beads, dispatches one sub-agent per bead, then closes or releases based on outcome.",
  phases: ["Claim", "Dispatch", "Finalize"]
};

// ── Configuration ─────────────────────────────────────────────────────────
// args.workspace    - path to workspace (default: current directory)
// args.maxBeads     - max beads to claim per run (default: 16, hard cap: 16)
// args.workerId     - assignee label written to claimed beads (default: dw-bead-worker)
// args.model        - model override for sub-agents (default: inherit session model)
const WORKSPACE  = args?.workspace  ?? ".";
const MAX_BEADS  = Math.min(args?.maxBeads ?? 16, 16);
const WORKER_ID  = args?.workerId   ?? "dw-bead-worker";
const MODEL      = args?.model;

// ── Helpers ───────────────────────────────────────────────────────────────

// br list/ready/claim emit JSONL — parse first valid object with an id field
function parseBeadLine(raw) {
  const text = typeof raw === "string" ? raw : raw;
  for (const line of text.trim().split("\n")) {
    const t = line.trim();
    if (!t || t === "{}") continue;
    try {
      const obj = JSON.parse(t);
      if (obj?.id) return obj;
    } catch {}
  }
  return null;
}

// Schema for bash execution results
const BASH_OUTPUT_SCHEMA = {
  type: "object",
  properties: {
    stdout: { type: "string" },
    stderr: { type: "string" },
    exit_code: { type: "number" }
  },
  required: ["stdout", "stderr", "exit_code"]
};

// Run a bash command via an agent and return stdout
async function runBash(command) {
  const result = await agent(
    `Execute this bash command and return ONLY the raw stdout as plain text (no markdown, no backticks):\n${command}`,
    { schema: BASH_OUTPUT_SCHEMA }
  );
  return result?.stdout ?? "";
}

// ── Phase 1: Claim (native atomic via br claim) ───────────────────────────
phase("Claim");
log(`workspace=${WORKSPACE}  worker=${WORKER_ID}  max=${MAX_BEADS}`);

const claimed = [];

for (let i = 0; i < MAX_BEADS; i++) {
  const raw = await runBash(`br claim --assignee "${WORKER_ID}" --json -w "${WORKSPACE}" 2>/dev/null`);
  const bead = parseBeadLine(raw);
  if (!bead) break;
  claimed.push(bead);
  log(`[${claimed.length}] ${bead.id}: ${bead.title}`);
}

if (claimed.length === 0) {
  log("No beads available");
  return { claimed: 0, closed: 0, released: 0 };
}

log(`${claimed.length} bead(s) claimed`);

// ── Load shared workspace context (once, reused across all agents) ─────────
let sharedContext = "";
for (const f of ["CLAUDE.md", "AGENTS.md", "README.md"]) {
  const raw = await runBash(`[ -f "${WORKSPACE}/${f}" ] && cat "${WORKSPACE}/${f}" 2>/dev/null || true`);
  if (raw) sharedContext += `\n\n### ${f}\n${raw}`;
}

// ── Phase 2: Dispatch (parallel, one agent per claimed bead) ───────────────
phase("Dispatch");

function buildPrompt(bead) {
  const desc   = bead.description        ? `### Description\n${bead.description}\n\n`        : "";
  const design = bead.design             ? `### Design\n${bead.design}\n\n`                   : "";
  const accept = bead.acceptance_criteria ? `### Acceptance Criteria\n${bead.acceptance_criteria}\n\n` : "";
  const notes  = bead.notes              ? `### Notes\n${bead.notes}\n\n`                    : "";

  return `You are a NEEDLE worker processing bead ${bead.id} in ${WORKSPACE}.

## Work Item
**ID:** ${bead.id}
**Title:** ${bead.title}
**Priority:** ${bead.priority ?? 0}
**Type:** ${bead.issue_type ?? "task"}

${desc}${design}${accept}${notes}## Workspace Context
${sharedContext || "(no context files found)"}

---

## Instructions

Implement the work described above completely. Work fully autonomously — do not ask clarifying questions or stop for confirmation. If something is ambiguous, make a reasonable decision and document it.

**On success:**
1. Commit all changes. Every commit message must include the trailer:
   \`Bead-Id: ${bead.id}\`
2. Push to origin.
3. Close this bead:
   \`\`\`
   br batch --json '[{"op":"close","id":"${bead.id}"}]' -w "${WORKSPACE}"
   \`\`\`

**If blocked** (missing credentials, genuine human decision required, or cannot proceed):
1. Release without closing:
   \`\`\`
   br update "${bead.id}" --status open --assignee "" -w "${WORKSPACE}"
   br label add "${bead.id}" blocked -w "${WORKSPACE}"
   \`\`\`

**If already complete or obsolete:**
Close it without making commits.`;
}

const BEAD_STATUS_SCHEMA = {
  type: "object",
  properties: {
    status: { type: "string", enum: ["open", "in_progress", "closed", "done", "unknown"] }
  },
  required: ["status"]
};

const results = await parallel(
  claimed.map(bead => async () => {
    const opts = { label: `${bead.id}: ${bead.title.slice(0, 45)}`, phase: "Dispatch" };
    if (MODEL) opts.model = MODEL;

    await agent(buildPrompt(bead), opts);

    // Read outcome from bead status
    const statusResult = await agent(
      `Run this command and return ONLY the status string (open/closed/done/in_progress/unknown), no other text:\nbr show "${bead.id}" --json -w "${WORKSPACE}" 2>/dev/null | grep -o '"status":"[^"]*"' | cut -d'"' -f4 || echo unknown`,
      { schema: BEAD_STATUS_SCHEMA }
    );
    const status = statusResult?.status ?? "unknown";

    if (status === "closed" || status === "done") {
      return { id: bead.id, title: bead.title, outcome: "closed" };
    }

    // Agent exited without closing — release for retry and label for visibility
    await runBash(`br update "${bead.id}" --status open --assignee "" -w "${WORKSPACE}" 2>/dev/null || true`);
    await runBash(`br label add "${bead.id}" failure -w "${WORKSPACE}" 2>/dev/null || true`);
    return { id: bead.id, title: bead.title, outcome: "released", finalStatus: status };
  })
);

// ── Phase 3: Finalize ──────────────────────────────────────────────────────
phase("Finalize");
await runBash(`br sync --flush-only -w "${WORKSPACE}" 2>/dev/null || true`);

const closed   = results.filter(r => r?.outcome === "closed").length;
const released = results.filter(r => r?.outcome === "released").length;

for (const r of results ?? []) {
  log(`${r?.outcome === "closed" ? "✓" : "✗"} ${r?.id}: ${r?.outcome}`);
}

log(`complete — ${closed}/${claimed.length} closed, ${released} released`);
return { claimed: claimed.length, closed, released };
